// The liveChatId belongs to the broadcast and does not change while it runs, so it is
// cached in static data. If the broadcast has not started, we stop QUIETLY here rather
// than hammering the messages endpoint with an empty id and burning quota.
const staticData = $getWorkflowStaticData('global');
const items = $input.all();
const live = items[0]?.json?.items?.[0];
const chatId = live?.snippet?.liveChatId || staticData.liveChatId;
if (!chatId) return [];
staticData.liveChatId = chatId;
return [{ json: { liveChatId: chatId, pageToken: staticData.pageToken || '' } }];

// Diff against what we have already forwarded. The API replays a window of messages on
// every poll, so WITHOUT this de-dupe Maya answers the same viewer every 5 seconds — the
// single most obvious way an AI host looks broken on a live stream.
const staticData = $getWorkflowStaticData('global');
const seen = new Set(staticData.seenIds || []);
const res = $input.first().json;
staticData.pageToken = res.nextPageToken || '';

const out = [];
for (const m of (res.items || [])) {
  const id = m.id;
  if (!id || seen.has(id)) continue;
  seen.add(id);
  const text = m.snippet?.displayMessage || m.snippet?.textMessageDetails?.messageText || '';
  if (!text.trim()) continue;
  out.push({ json: {
    platform: 'youtube',
    msg_id: id,
    name: m.authorDetails?.displayName || 'viewer',
    handle: m.authorDetails?.channelId || '',
    text: text.trim(),
    ts: m.snippet?.publishedAt || new Date().toISOString(),
  }});
}
// keep the seen-set bounded: a long stream must not grow memory without limit
staticData.seenIds = Array.from(seen).slice(-2000);
return out;
